[{"order":1,"type":"heading","text":"Tutorial: Application Insights and Distributed Tracing in Azure"},{"order":2,"type":"paragraph","text":"Distributed tracing allows you to track a request as it flows through multiple services, microservices, and databases in Azure. Application Insights, a feature of Azure Monitor, provides out-of-the-box support for distributed tracing using W3C Trace Context standards."},{"order":3,"type":"subheading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"An active Azure subscription."},{"order":5,"type":"bullet_point","text":"An existing Application Insights resource in the Azure Portal."},{"order":6,"type":"bullet_point","text":".NET 6.0 SDK or later installed on your development machine."},{"order":7,"type":"subheading","text":"Step 1: Configure Application Insights in a .NET Web API"},{"order":8,"type":"paragraph","text":"First, install the official Microsoft Application Insights NuGet package for worker services and web applications."},{"order":9,"type":"code","text":"dotnet add package Microsoft.ApplicationInsights.AspNetCore"},{"order":10,"type":"subheading","text":"Step 2: Update Application Settings"},{"order":11,"type":"paragraph","text":"Add your Application Insights connection string to the appsettings.json file of your application."},{"order":12,"type":"code","text":"{
  "Logging": {
    "LogLevel": {
      "Default": "Information",
      "Microsoft.AspNetCore": "Warning"
    }
  },
  "ApplicationInsights": {
    "ConnectionString": "InstrumentationKey=your-guid-here;IngestionEndpoint=https://yourlocation.in.applicationinsights.azure.com/"
  },
  "AllowedHosts": "*"
}"},{"order":13,"type":"subheading","text":"Step 3: Register Application Insights in Program.cs"},{"order":14,"type":"paragraph","text":"Enable telemetry collection by registering the Application Insights services in your Program.cs file."},{"order":15,"type":"code","text":"var builder = WebApplication.CreateBuilder(args);

// Add Application Insights telemetry
builder.Services.AddApplicationInsightsTelemetry();

builder.Services.AddControllers();
var app = builder.Build();

app.MapControllers();
app.Run();"},{"order":16,"type":"subheading","text":"Step 4: Implement Custom Tracing and Dependencies"},{"order":17,"type":"paragraph","text":"Application Insights automatically tracks incoming HTTP requests and outgoing HttpClient calls. You can use standard .NET Activity sources to create custom telemetry spans."},{"order":18,"type":"code","text":"using System.Diagnostics;
using Microsoft.AspNetCore.Mvc;

[ApiController]
[Route("[controller]")]
public class SampleController : ControllerBase
{
    private static readonly ActivitySource MyActivitySource = new ActivitySource("MyCompany.MyService");

    [HttpGet("process")]
    public async Task<IActionResult> ProcessData()
    {
        using (Activity? activity = MyActivitySource.StartActivity("ProcessingCustomWork"))
        {
            activity?.SetTag("custom.state", "InProgress");

            // Simulate business logic
            await Task.Delay(500);

            activity?.SetTag("custom.state", "Completed");
            return Ok(new { status = "Success" });
        }
    }
}"},{"order":19,"type":"subheading","text":"Step 5: View Distributed Traces in Azure Portal"},{"order":20,"type":"bullet_point","text":"Navigate to the Azure Portal and open your Application Insights resource."},{"order":21,"type":"bullet_point","text":"Select 'Transaction search' or 'Application Map' from the left-hand navigation menu."},{"order":22,"type":"bullet_point","text":"Click on any specific request to view the end-to-end transaction timeline and trace details across multiple microservices."}]
